//! Shared platform shapes: identities, references, search options, items, and result pages.
//!
//! Each platform's own shapes live in its own module and join the shared enums here as one
//! variant; see `docs/spec/forager/07-platforms.md`.

use std::fmt;
use std::path::PathBuf;

use serde::{Deserialize, Serialize, Serializer};
use thiserror::Error;

use super::ProviderAttempt;
use super::platform_arxiv::{ArxivItemData, ArxivRef, ArxivSearchOptions};
use super::platform_hn::{HnItemData, HnRef, HnSearchOptions};
use super::platform_scholar::{ScholarItemData, ScholarRef, ScholarSearchOptions};
use super::platform_ssrn::{SsrnItemData, SsrnRef};
use super::platform_ssrn_search::SsrnSearchOptions;
use super::platform_x::{XPostData, XRef, XSearchOptions};
use super::platform_xiaohongshu::{
    AccessToken, XiaohongshuItemData, XiaohongshuNoteData, XiaohongshuRef, XiaohongshuSearchOptions,
};

#[derive(Clone, Copy, Debug, Deserialize, Eq, Hash, Ord, PartialEq, PartialOrd, Serialize)]
#[serde(rename_all = "snake_case")]
/// A built-in external content source with its own identity space.
pub enum Platform {
    /// The arXiv preprint server.
    Arxiv,
    /// The Social Science Research Network (SSRN).
    Ssrn,
    /// Google Scholar, an index of papers across publishers.
    Scholar,
    /// Xiaohongshu (小红书), a social platform of user notes.
    Xiaohongshu,
    /// X (formerly Twitter), a social platform of short posts.
    X,
    /// Hacker News, a technology news and discussion site.
    Hn,
}

impl Platform {
    /// Every built-in platform.
    pub const ALL: [Self; 6] = [
        Self::Arxiv,
        Self::Ssrn,
        Self::Scholar,
        Self::Xiaohongshu,
        Self::X,
        Self::Hn,
    ];

    /// Returns the stable platform identifier used by commands and configuration.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Arxiv => "arxiv",
            Self::Ssrn => "ssrn",
            Self::Scholar => "scholar",
            Self::Xiaohongshu => "xiaohongshu",
            Self::X => "x",
            Self::Hn => "hn",
        }
    }
}

impl fmt::Display for Platform {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(self.as_str())
    }
}

#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "snake_case")]
/// How much of a platform item a result carries; each platform defines what each depth means.
pub enum ContentDepth {
    /// Bibliographic information only, without an abstract.
    Metadata,
    /// A short excerpt.
    Snippet,
    /// Metadata and the author-written summary, never the full text.
    Abstract,
    /// The complete body.
    FullText,
    /// A post together with its conversation.
    Thread,
}

impl ContentDepth {
    /// Returns the stable depth identifier used by commands and output.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Metadata => "metadata",
            Self::Snippet => "snippet",
            Self::Abstract => "abstract",
            Self::FullText => "full_text",
            Self::Thread => "thread",
        }
    }
}

#[derive(Debug, Error)]
/// An input that is not a recognizable reference or original URL for the platform.
pub struct PlatformRefError {
    pub(super) platform: Platform,
    /// The input to echo, or `None` for a platform whose URLs may carry an access token.
    pub(super) input: Option<String>,
    pub(super) hint: &'static str,
}

impl fmt::Display for PlatformRefError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(formatter, "unrecognized {} reference", self.platform)?;
        if let Some(input) = &self.input {
            write!(formatter, " `{input}`")?;
        }
        write!(formatter, "; {}", self.hint)
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
/// The typed identity of a platform entity.
///
/// The display form is the ref string, such as `arxiv:2401.01234v2`. Parsing the canonical URL
/// of a ref returns the same ref.
pub enum PlatformRef {
    /// An arXiv paper.
    Arxiv(ArxivRef),
    /// An SSRN paper.
    Ssrn(SsrnRef),
    /// A Google Scholar paper cluster.
    Scholar(ScholarRef),
    /// A Xiaohongshu note.
    Xiaohongshu(XiaohongshuRef),
    /// An X post.
    X(XRef),
    /// A Hacker News item.
    Hn(HnRef),
}

impl PlatformRef {
    /// Parses a ref string or an original platform URL without any network access.
    ///
    /// # Errors
    ///
    /// Returns [`PlatformRefError`] when the input is not recognizable for `platform`.
    pub fn parse(platform: Platform, input: &str) -> Result<Self, PlatformRefError> {
        match platform {
            Platform::Arxiv => ArxivRef::parse(input).map(Self::Arxiv),
            Platform::Ssrn => SsrnRef::parse(input).map(Self::Ssrn),
            Platform::Scholar => ScholarRef::parse(input).map(Self::Scholar),
            Platform::Xiaohongshu => XiaohongshuRef::parse(input).map(Self::Xiaohongshu),
            Platform::X => XRef::parse(input).map(Self::X),
            Platform::Hn => HnRef::parse(input).map(Self::Hn),
        }
    }

    /// Returns the platform that owns this identity.
    #[must_use]
    pub const fn platform(&self) -> Platform {
        match self {
            Self::Arxiv(_) => Platform::Arxiv,
            Self::Ssrn(_) => Platform::Ssrn,
            Self::Scholar(_) => Platform::Scholar,
            Self::Xiaohongshu(_) => Platform::Xiaohongshu,
            Self::X(_) => Platform::X,
            Self::Hn(_) => Platform::Hn,
        }
    }

    /// Returns the platform-owned entity kind.
    #[must_use]
    pub const fn kind(&self) -> &'static str {
        match self {
            Self::Arxiv(_) | Self::Ssrn(_) | Self::Scholar(_) => "paper",
            Self::Xiaohongshu(_) => "note",
            Self::X(_) => "post",
            Self::Hn(_) => "item",
        }
    }

    /// Returns the canonical URL; it carries a version only when the ref does.
    #[must_use]
    pub fn canonical_url(&self) -> String {
        match self {
            Self::Arxiv(reference) => reference.canonical_url(),
            Self::Ssrn(reference) => reference.canonical_url(),
            Self::Scholar(reference) => reference.canonical_url(),
            Self::Xiaohongshu(reference) => reference.canonical_url(),
            Self::X(reference) => reference.canonical_url(),
            Self::Hn(reference) => reference.canonical_url(),
        }
    }
}

impl fmt::Display for PlatformRef {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Arxiv(reference) => write!(formatter, "arxiv:{reference}"),
            Self::Ssrn(reference) => write!(formatter, "ssrn:{reference}"),
            Self::Scholar(reference) => write!(formatter, "scholar:{reference}"),
            Self::Xiaohongshu(reference) => write!(formatter, "xiaohongshu:{reference}"),
            Self::X(reference) => write!(formatter, "x:{reference}"),
            Self::Hn(reference) => write!(formatter, "hn:{reference}"),
        }
    }
}

impl Serialize for PlatformRef {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.collect_str(self)
    }
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(tag = "platform", rename_all = "snake_case")]
/// The typed search options of one platform.
pub enum PlatformSearchOptions {
    /// arXiv options.
    Arxiv(ArxivSearchOptions),
    /// SSRN options.
    Ssrn(SsrnSearchOptions),
    /// Google Scholar options.
    Scholar(ScholarSearchOptions),
    /// Xiaohongshu options.
    Xiaohongshu(XiaohongshuSearchOptions),
    /// X options.
    X(XSearchOptions),
    /// Hacker News options.
    Hn(HnSearchOptions),
}

impl PlatformSearchOptions {
    /// Returns the default options of `platform`.
    #[must_use]
    pub fn defaults(platform: Platform) -> Self {
        match platform {
            Platform::Arxiv => Self::Arxiv(ArxivSearchOptions::default()),
            Platform::Ssrn => Self::Ssrn(SsrnSearchOptions::default()),
            Platform::Scholar => Self::Scholar(ScholarSearchOptions::default()),
            Platform::Xiaohongshu => Self::Xiaohongshu(XiaohongshuSearchOptions::default()),
            Platform::X => Self::X(XSearchOptions::default()),
            Platform::Hn => Self::Hn(HnSearchOptions::default()),
        }
    }

    /// Returns the platform these options belong to.
    #[must_use]
    pub const fn platform(&self) -> Platform {
        match self {
            Self::Arxiv(_) => Platform::Arxiv,
            Self::Ssrn(_) => Platform::Ssrn,
            Self::Scholar(_) => Platform::Scholar,
            Self::Xiaohongshu(_) => Platform::Xiaohongshu,
            Self::X(_) => Platform::X,
            Self::Hn(_) => Platform::Hn,
        }
    }
}

#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
/// A platform search request; a page cursor encodes it completely.
pub(crate) struct PlatformSearchRequest {
    pub(crate) query: String,
    pub(crate) limit: u16,
    pub(crate) options: PlatformSearchOptions,
    /// The route-owned position of the requested page; absent for the first page.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub(crate) page: Option<String>,
}

impl PlatformSearchRequest {
    /// Checks the cross-field rules that argument parsing cannot express.
    pub(crate) fn validate(&self) -> Result<(), String> {
        match &self.options {
            PlatformSearchOptions::Arxiv(options) => options.validate(&self.query, self.limit),
            PlatformSearchOptions::Ssrn(options) => options.validate(&self.query, self.limit),
            PlatformSearchOptions::Scholar(options) => options.validate(&self.query, self.limit),
            PlatformSearchOptions::Xiaohongshu(_) => {
                XiaohongshuSearchOptions::validate(&self.query, self.limit)
            }
            PlatformSearchOptions::X(options) => options.validate(&self.query, self.limit),
            PlatformSearchOptions::Hn(options) => options.validate(&self.query, self.limit),
        }
    }
}

#[derive(Clone, Debug, Serialize)]
/// One platform entity in a result.
pub struct PlatformItem {
    #[serde(rename = "ref")]
    pub reference: PlatformRef,
    pub url: String,
    pub depth: ContentDepth,
    /// The item title; `null` for a platform whose entities have none, such as X posts.
    pub title: Option<String>,
    pub authors: Vec<String>,
    pub published: Option<String>,
    #[serde(flatten)]
    pub data: PlatformItemData,
}

#[derive(Clone, Debug, Serialize)]
#[serde(untagged)]
/// The platform-owned fields of an item.
pub enum PlatformItemData {
    /// arXiv metadata.
    Arxiv(ArxivItemData),
    /// SSRN metadata.
    Ssrn(SsrnItemData),
    /// Google Scholar metadata.
    Scholar(ScholarItemData),
    /// Xiaohongshu note-card fields of a search result.
    Xiaohongshu(XiaohongshuItemData),
    /// Xiaohongshu fields of a fetched note.
    XiaohongshuNote(XiaohongshuNoteData),
    /// X fields of a post.
    X(XPostData),
    /// Hacker News fields of an item.
    Hn(HnItemData),
}

#[derive(Clone, Debug, Serialize)]
/// One page of platform search results.
pub struct PlatformSearchPage {
    pub platform: Platform,
    /// The route that produced the page.
    pub provider: &'static str,
    pub items: Vec<PlatformItem>,
    /// An opaque cursor for the next page, or `null` when the route issues no cursor that
    /// another command can continue from. `null` alone does not prove the results are
    /// exhausted: Xiaohongshu search never issues a cursor.
    pub next_cursor: Option<String>,
    #[serde(rename = "provider_attempts", skip_serializing_if = "Vec::is_empty")]
    pub attempts: Vec<ProviderAttempt>,
    #[serde(skip)]
    pub diagnostic: Option<String>,
}

/// One route's search result before cursor encoding.
pub(crate) struct PlatformSearchOutcome {
    pub(crate) items: Vec<PlatformItem>,
    /// The route-owned position of the next page, when one exists.
    pub(crate) next_page: Option<String>,
    pub(crate) attempts: Vec<ProviderAttempt>,
    pub(crate) diagnostic: Option<String>,
}

#[derive(Clone, Debug)]
/// A platform fetch request.
pub(crate) struct PlatformFetchRequest {
    pub(crate) reference: PlatformRef,
    pub(crate) depth: ContentDepth,
    /// The access token that opens the entity, for a platform that needs one; it never reaches
    /// the ref, the canonical URL, or the journal.
    pub(crate) access: Option<AccessToken>,
}

/// One route's fetch result before the full-text stage.
pub(crate) struct PlatformFetchOutcome {
    /// The metadata item; its ref carries the version the platform returned.
    pub(crate) item: PlatformItem,
    /// The full-text source; `Urls` is empty unless the request asks for the full text. At
    /// thread depth, a `Native` body is the discussion document, delivered like a full text.
    pub(crate) content_source: FullTextSource,
    pub(crate) attempts: Vec<ProviderAttempt>,
    pub(crate) diagnostic: Option<String>,
}

#[derive(Clone, Debug)]
/// Where the full text of an item lives: URLs to read in order, one local file the route
/// produced and verified in the same command, or the Markdown body the route itself read and
/// verified in the same attempt.
pub(crate) enum FullTextSource {
    /// URLs to read in order; empty unless the request asks for the full text.
    Urls(Vec<String>),
    /// One verified local file.
    LocalFile(LocalFile),
    /// The platform-native Markdown body; it needs no Web Fetch provider.
    Native(String),
}

#[derive(Clone, Debug)]
/// A local file one stage of a command hands to a later stage, with its media type.
pub(crate) struct LocalFile {
    pub(crate) path: PathBuf,
    pub(crate) media_type: LocalMediaType,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
/// The media type of a [`LocalFile`].
pub(crate) enum LocalMediaType {
    /// A PDF document.
    Pdf,
}

impl LocalMediaType {
    /// Returns the MIME type string.
    pub(crate) const fn as_str(self) -> &'static str {
        match self {
            Self::Pdf => "application/pdf",
        }
    }

    /// Returns the conventional file extension.
    pub(crate) const fn extension(self) -> &'static str {
        match self {
            Self::Pdf => "pdf",
        }
    }
}

#[derive(Clone, Debug, Serialize)]
/// One fetched platform item: its metadata and, at full-text depth, a reference to its body.
pub struct PlatformFetchResult {
    pub platform: Platform,
    /// The route that returned the metadata.
    pub provider: &'static str,
    #[serde(flatten)]
    pub item: PlatformItem,
    #[serde(flatten)]
    pub content: Option<PlatformContent>,
    #[serde(rename = "provider_attempts", skip_serializing_if = "Vec::is_empty")]
    pub attempts: Vec<ProviderAttempt>,
    #[serde(skip)]
    pub diagnostic: Option<String>,
}

#[derive(Clone, Debug, Serialize)]
/// The full text of a platform item; the body itself never serializes.
pub struct PlatformContent {
    /// The URL the body was read from; for a body converted from a local file or read natively
    /// by the route, the item's canonical URL, which names the source but may not open
    /// anonymously.
    #[serde(rename = "content_url")]
    pub url: String,
    /// The provider that produced the Markdown: the Web Fetch provider, or the route itself for
    /// a native body.
    #[serde(rename = "content_provider")]
    pub provider: &'static str,
    /// The local Markdown file that holds the body, once written.
    #[serde(rename = "content_path", skip_serializing_if = "Option::is_none")]
    pub path: Option<String>,
    /// The body length in characters.
    #[serde(rename = "content_len")]
    pub len: usize,
    /// The original PDF kept next to the Markdown, when the caller asked to keep it.
    #[serde(rename = "pdf_path", skip_serializing_if = "Option::is_none")]
    pub pdf_path: Option<String>,
    /// The kept PDF size in bytes.
    #[serde(rename = "pdf_bytes", skip_serializing_if = "Option::is_none")]
    pub pdf_bytes: Option<u64>,
    #[serde(skip)]
    pub text: String,
    /// The local file the body was converted from; delivery keeps or removes it.
    #[serde(skip)]
    pub(crate) source_file: Option<LocalFile>,
}

impl PlatformContent {
    /// Wraps a body read from `url`; the path stays empty until the body is written.
    #[must_use]
    pub fn new(url: String, provider: &'static str, text: String) -> Self {
        Self {
            url,
            provider,
            path: None,
            len: text.chars().count(),
            pdf_path: None,
            pdf_bytes: None,
            text,
            source_file: None,
        }
    }
}

//! Platform fetch: the metadata route chain and the full-text stage.
//!
//! The platform's fetch routes form a fallback chain that returns the item metadata; a metadata
//! failure ends the command. At full-text depth, the route that answered declares the full-text
//! source of the version it returned: URLs to read in order or one verified local file, each of
//! which runs the global Web Fetch chain until one succeeds, or a native body the route already
//! read and verified, which needs no Web Fetch. Route adapters never import Web Fetch providers.
//!
//! At thread depth each platform declares how the discussion is delivered: a route that returns
//! a native body (Hacker News) has it delivered by reference like a full text; any other route
//! carries the thread inline in its item (X).

use reqwest::Client;

use crate::catalog::{self, PlatformOperation, ProviderId};
use crate::chain::{
    self, BudgetPolicy, ChainSettings, ChainStep, DiagnosticMerge, StepSuccess, StepVerdict,
    TerminalPolicy,
};
use crate::config::{PlatformRouteConfig, PlatformRuntimeConfig, WebFetchRuntimeConfig};
use crate::engine;
use crate::net::{RetryPolicy, combine_diagnostics};
use crate::platform_chain::{
    PlatformPreflightError, operation_target, plan_routes, route_candidates, route_identity,
};
use crate::providers::{self, FetchRequest, FetchSource};
use crate::types::{
    AttemptErrorKind, ContentDepth, Deadline, FullTextSource, LocalFile, Platform, PlatformContent,
    PlatformFetchRequest, PlatformFetchResult, PlatformItem, ProviderAttempt, ProviderError,
};

/// The routes a platform fetch runs, in order, and the routes skipped before it runs.
pub(crate) struct PlatformFetchPlan {
    platform: Platform,
    request: PlatformFetchRequest,
    routes: Vec<PlatformRouteConfig>,
    skipped: Vec<ProviderAttempt>,
}

impl PlatformFetchPlan {
    /// Returns whether running the plan may read a full text through Web Fetch: the request asks
    /// for the full text and some planned route does not read it natively.
    pub(crate) fn needs_web_fetch(&self) -> bool {
        self.request.depth == ContentDepth::FullText
            && self
                .routes
                .iter()
                .any(|route| !catalog::registration(route.route()).native_full_text)
    }
}

/// Plans a fetch over the configured routes that can serve the requested depth.
pub(crate) fn plan_fetch(
    config: &PlatformRuntimeConfig,
    request: PlatformFetchRequest,
) -> Result<PlatformFetchPlan, PlatformPreflightError> {
    let plan = plan_routes(
        PlatformOperation::Fetch.as_str(),
        config.platform(),
        &config.order_key(),
        catalog::platform(config.platform()).routes(PlatformOperation::Fetch),
        &route_candidates(config),
        None,
        |id| providers::platform_fetch_support(id, &request),
    )?;
    Ok(PlatformFetchPlan {
        platform: config.platform(),
        request,
        routes: plan.routes.into_iter().map(|(_, config)| config).collect(),
        skipped: plan.skipped,
    })
}

/// A platform fetch terminal failure. When the route produced a local full-text file before
/// the failure, it rides along so delivery can keep it for the user.
pub(crate) struct PlatformFetchError {
    pub(crate) error: ProviderError,
    pub(crate) source_file: Option<LocalFile>,
}

/// Runs a planned fetch. At full-text depth the body comes from `web_fetch`, which must have a
/// configured provider when [`PlatformFetchPlan::needs_web_fetch`] says so.
pub(crate) async fn fetch(
    plan: PlatformFetchPlan,
    web_fetch: WebFetchRuntimeConfig,
    client: Client,
    retry_policy: RetryPolicy,
    deadline: Deadline,
    verbose: bool,
) -> Result<PlatformFetchResult, PlatformFetchError> {
    let PlatformFetchPlan {
        platform,
        request,
        routes,
        skipped,
    } = plan;
    let mut attempts = skipped;
    let metadata = match fetch_metadata(
        platform,
        &request,
        routes,
        client.clone(),
        retry_policy,
        deadline,
        verbose,
    )
    .await
    {
        Ok(metadata) => metadata,
        Err(mut error) => {
            attempts.append(&mut error.attempts);
            error.attempts = attempts;
            return Err(PlatformFetchError {
                error,
                source_file: None,
            });
        }
    };
    attempts.extend(metadata.attempts);
    let mut item = metadata.item;
    let mut diagnostic = metadata.diagnostic;
    let mut content = None;
    if request.depth == ContentDepth::Thread
        && let FullTextSource::Native(body) = metadata.content_source
    {
        content = Some(PlatformContent::new(
            item.url.clone(),
            metadata.route.name(),
            body,
        ));
    } else if request.depth == ContentDepth::FullText {
        let full_text = match metadata.content_source {
            FullTextSource::Native(body) => Ok(FullText {
                content: PlatformContent::new(item.url.clone(), metadata.route.name(), body),
                attempts: Vec::new(),
                diagnostic: None,
            }),
            FullTextSource::Urls(urls) => {
                read_url_full_text(urls, &web_fetch, &client, retry_policy, deadline)
                    .await
                    .map_err(|error| (error, None))
            }
            FullTextSource::LocalFile(file) => read_file_full_text(
                &file,
                &item.url,
                &web_fetch,
                &client,
                retry_policy,
                deadline,
            )
            .await
            .map_err(|error| (error, Some(file))),
        };
        match full_text {
            Ok(body) => {
                attempts.extend(body.attempts);
                item.depth = ContentDepth::FullText;
                diagnostic =
                    combine_diagnostics([diagnostic, body.diagnostic].into_iter().flatten());
                content = Some(body.content);
            }
            Err((mut error, source_file)) => {
                attempts.append(&mut error.attempts);
                error.attempts = attempts;
                error.verbose = verbose;
                error.diagnostic =
                    combine_diagnostics([diagnostic, error.diagnostic].into_iter().flatten());
                return Err(PlatformFetchError { error, source_file });
            }
        }
    }
    Ok(PlatformFetchResult {
        platform,
        provider: metadata.route.name(),
        item,
        content,
        attempts: if verbose { attempts } else { Vec::new() },
        diagnostic,
    })
}

struct Metadata {
    route: ProviderId,
    item: PlatformItem,
    content_source: FullTextSource,
    attempts: Vec<ProviderAttempt>,
    diagnostic: Option<String>,
}

async fn fetch_metadata(
    platform: Platform,
    request: &PlatformFetchRequest,
    routes: Vec<PlatformRouteConfig>,
    client: Client,
    retry_policy: RetryPolicy,
    deadline: Deadline,
    verbose: bool,
) -> Result<Metadata, ProviderError> {
    let steps = routes
        .into_iter()
        .map(|context| ChainStep {
            context,
            configured: true,
            gate_attempt: None,
        })
        .collect();
    let outcome = chain::run_chain(
        steps,
        ChainSettings {
            target: operation_target(platform, PlatformOperation::Fetch.as_str()),
            budget_policy: BudgetPolicy::SlicedEven {
                skipped_message: "skipped to preserve fallback deadline budget",
            },
            fallback_off: false,
            diagnostic_merge: DiagnosticMerge::Join,
            terminal: TerminalPolicy::ChainWide {
                verbose,
                exhausted_message: "platform fetch deadline elapsed",
            },
            identity: &route_identity,
            continue_on_failure: &chain::always_continue,
        },
        deadline,
        |config, step_deadline| {
            let client = client.clone();
            async move {
                let route = config.route();
                let adapter =
                    providers::build_platform_fetch(config, client, retry_policy, step_deadline);
                match adapter.fetch(request).await {
                    Ok(outcome) => StepVerdict::Accepted(StepSuccess {
                        value: (route, outcome.item, outcome.content_source),
                        attempts: outcome.attempts,
                        diagnostic: outcome.diagnostic,
                    }),
                    Err(error) => StepVerdict::Failed(error),
                }
            }
        },
    )
    .await?;
    let (route, item, content_source) = outcome.value;
    Ok(Metadata {
        route,
        item,
        content_source,
        attempts: outcome.attempts,
        diagnostic: outcome.diagnostic,
    })
}

struct FullText {
    content: PlatformContent,
    attempts: Vec<ProviderAttempt>,
    diagnostic: Option<String>,
}

/// Reads the first URL whose Web Fetch chain succeeds. A URL with a later fallback gets half of
/// the remaining budget; the last URL's failure is the terminal state.
async fn read_url_full_text(
    urls: Vec<String>,
    web_fetch: &WebFetchRuntimeConfig,
    client: &Client,
    retry_policy: RetryPolicy,
    deadline: Deadline,
) -> Result<FullText, ProviderError> {
    let mut attempts = Vec::new();
    let mut last_error = None;
    let count = urls.len();
    for (index, url) in urls.into_iter().enumerate() {
        let stage_deadline = if index + 1 < count {
            fallback_share(deadline)
        } else {
            deadline
        };
        // The attempts of every stage are kept; the caller drops them unless verbose.
        let request = FetchRequest {
            source: FetchSource::Url(url.clone()),
            verbose: true,
        };
        match engine::fetch(
            request,
            web_fetch.clone(),
            client.clone(),
            retry_policy,
            stage_deadline,
        )
        .await
        {
            Ok(outcome) => {
                attempts.extend(outcome.attempts);
                return Ok(FullText {
                    content: PlatformContent::new(url, outcome.provider, outcome.content),
                    attempts,
                    diagnostic: outcome.diagnostic,
                });
            }
            Err(mut error) => {
                attempts.append(&mut error.attempts);
                last_error = Some(error);
            }
        }
    }
    let mut error = last_error.unwrap_or_else(|| ProviderError {
        kind: AttemptErrorKind::Runtime,
        message: "the route declared no full-text URL".into(),
        attempts: Vec::new(),
        verbose: false,
        diagnostic: None,
        redirected_library_id: None,
    });
    error.attempts = attempts;
    Err(error)
}

/// Converts a verified local file through the Web Fetch chain. The content URL is the item's
/// canonical URL: the body originates from the platform, not from a fetchable address.
async fn read_file_full_text(
    file: &LocalFile,
    item_url: &str,
    web_fetch: &WebFetchRuntimeConfig,
    client: &Client,
    retry_policy: RetryPolicy,
    deadline: Deadline,
) -> Result<FullText, ProviderError> {
    let request = FetchRequest {
        source: FetchSource::LocalFile(file.clone()),
        verbose: true,
    };
    let outcome = engine::fetch(
        request,
        web_fetch.clone(),
        client.clone(),
        retry_policy,
        deadline,
    )
    .await?;
    let mut content = PlatformContent::new(item_url.to_owned(), outcome.provider, outcome.content);
    content.source_file = Some(file.clone());
    Ok(FullText {
        content,
        attempts: outcome.attempts,
        diagnostic: outcome.diagnostic,
    })
}

/// Returns a deadline for half of the remaining budget, keeping the other half for fallback.
fn fallback_share(deadline: Deadline) -> Deadline {
    deadline
        .remaining()
        .map_or(deadline, |remaining| Deadline::new(remaining / 2))
}

//! X ask: the route chain of the single-route `ask` operation.
//!
//! Planning follows every platform operation: order ∩ the operation's route set ∩ configured
//! routes. The route set lives in the provider factory because one route implements the
//! operation. An answer is never empty, so every route success is accepted as is.

use reqwest::Client;

use crate::chain::{
    self, BudgetPolicy, ChainSettings, ChainStep, DiagnosticMerge, StepSuccess, StepVerdict,
    TerminalPolicy,
};
use crate::config::{PlatformRouteConfig, PlatformRuntimeConfig};
use crate::net::RetryPolicy;
use crate::platform_chain::{
    PlatformPreflightError, operation_target, plan_routes, route_candidates, route_identity,
};
use crate::providers;
use crate::types::{
    ASK, Deadline, Platform, ProviderAttempt, ProviderError, XAskRequest, XAskResult,
};

/// The routes an ask runs, in order, and the routes skipped before it runs.
pub(crate) struct AskPlan {
    request: XAskRequest,
    routes: Vec<PlatformRouteConfig>,
    skipped: Vec<ProviderAttempt>,
}

/// Plans an ask; `config` is X's.
pub(crate) fn plan_ask(
    config: &PlatformRuntimeConfig,
    request: XAskRequest,
) -> Result<AskPlan, PlatformPreflightError> {
    let plan = plan_routes(
        ASK,
        config.platform(),
        &config.order_key(),
        providers::X_ASK_ROUTES,
        &route_candidates(config),
        None,
        providers::x_ask_support,
    )?;
    Ok(AskPlan {
        request,
        routes: plan.routes.into_iter().map(|(_, config)| config).collect(),
        skipped: plan.skipped,
    })
}

/// Runs a planned ask.
pub(crate) async fn run_ask(
    plan: AskPlan,
    client: Client,
    retry_policy: RetryPolicy,
    deadline: Deadline,
    verbose: bool,
) -> Result<XAskResult, ProviderError> {
    let AskPlan {
        request,
        routes,
        mut skipped,
    } = plan;
    let request = &request;
    let steps = routes
        .into_iter()
        .map(|context| ChainStep {
            context,
            configured: true,
            gate_attempt: None,
        })
        .collect();
    let result = chain::run_chain(
        steps,
        ChainSettings {
            target: operation_target(Platform::X, ASK),
            budget_policy: BudgetPolicy::SlicedEven {
                skipped_message: "skipped to preserve fallback deadline budget",
            },
            fallback_off: false,
            diagnostic_merge: DiagnosticMerge::Join,
            terminal: TerminalPolicy::ChainWide {
                verbose,
                exhausted_message: "platform ask deadline elapsed",
            },
            identity: &route_identity,
            continue_on_failure: &chain::always_continue,
        },
        deadline,
        |config: PlatformRouteConfig, step_deadline| {
            let client = client.clone();
            async move {
                let route = config.route();
                match providers::x_ask(config, client, retry_policy, step_deadline, request).await {
                    Ok(outcome) => StepVerdict::Accepted(StepSuccess {
                        value: (route, outcome.answer, outcome.sources),
                        attempts: outcome.attempts,
                        diagnostic: outcome.diagnostic,
                    }),
                    Err(error) => StepVerdict::Failed(error),
                }
            }
        },
    )
    .await;
    match result {
        Ok(outcome) => {
            let (route, answer, sources) = outcome.value;
            skipped.extend(outcome.attempts);
            Ok(XAskResult {
                platform: Platform::X,
                provider: route.name(),
                query: request.query.clone(),
                answer,
                sources,
                attempts: if verbose { skipped } else { Vec::new() },
                diagnostic: outcome.diagnostic,
            })
        }
        Err(mut error) => {
            skipped.append(&mut error.attempts);
            error.attempts = skipped;
            Err(error)
        }
    }
}

//! The `serpapi` route: SerpApi's search endpoint, keyed by the Provider Credential Pool.
//!
//! This module owns what every SerpApi engine shares: the endpoint, the `api_key` parameter,
//! the HTTP 200 success protocol, and credential redaction. Engine modules own their request
//! parameters, response decoding, and support checks; the account module owns the free
//! per-key quota report.

use std::time::Duration;

use reqwest::Client;
use serde::Deserialize;
use serde_json::Value;

use crate::catalog::ProviderId;
use crate::config::KeyedHttpRouteRuntimeConfig;
use crate::credentials::CredentialPool;
use crate::net::{AttemptFailure, ProviderResponseBody, RetryPolicy, read_complete_protocol};
use crate::providers::execution::{ExecutionOutcome, ExecutionSettings, execute_v2};
use crate::providers::shared::redacted_urls_message;
use crate::redact::Secret;
use crate::types::{AttemptErrorKind, AttemptTarget, Deadline, ProviderError};

const ROUTE: ProviderId = ProviderId::Serpapi;
#[path = "serpapi_account.rs"]
mod account;
#[path = "serpapi_scholar.rs"]
mod scholar;
pub(crate) use account::KeyAccount;
pub(crate) use scholar::{cited_by_support, fetch_support, search_support};

pub(crate) struct Serpapi {
    url: String,
    timeout_seconds: u64,
    client: Client,
    credentials: CredentialPool,
    retry_policy: RetryPolicy,
    deadline: Deadline,
}

/// The results of one SerpApi search that passed the HTTP 200 success protocol.
#[derive(Debug, PartialEq)]
enum SearchResults {
    /// A non-empty `organic_results` array, and whether SerpApi offers a next page.
    Found {
        results: Vec<Value>,
        has_next_page: bool,
    },
    /// SerpApi reported the search as `Fully empty`.
    Empty,
}

/// Returns the failure of an HTTP 200 response that the success protocol or an engine refuses.
fn refusal(kind: AttemptErrorKind, message: String) -> AttemptFailure {
    AttemptFailure {
        kind,
        status: Some(200),
        message,
    }
}

impl Serpapi {
    pub(crate) fn new(
        config: KeyedHttpRouteRuntimeConfig,
        client: Client,
        credentials: CredentialPool,
        retry_policy: RetryPolicy,
        deadline: Deadline,
    ) -> Self {
        Self {
            url: config.url,
            timeout_seconds: config.timeout_seconds,
            client,
            credentials,
            retry_policy,
            deadline,
        }
    }

    /// Runs one logical search of the named platform operation with credential claim, rotation,
    /// and retry. `decode` turns the results into the operation's value inside the attempt, so a
    /// refusal is that attempt's failure.
    async fn run<T>(
        &self,
        operation: &'static str,
        parameters: &[(&'static str, String)],
        decode: impl Fn(SearchResults) -> Result<T, AttemptFailure>,
    ) -> Result<ExecutionOutcome<T>, ProviderError> {
        let decode = &decode;
        execute_v2(
            &self.credentials,
            self.settings(AttemptTarget::platform(
                scholar::PLATFORM.as_str(),
                operation,
            )),
            |credential, _| async move {
                let results = self.send_once(parameters, &credential).await?;
                decode(results)
                    .map(|value| (Some(200), value))
                    .map_err(|failure| self.redacted(failure))
            },
        )
        .await
    }

    async fn send_once(
        &self,
        parameters: &[(&'static str, String)],
        credential: &Secret,
    ) -> Result<SearchResults, AttemptFailure> {
        let body = self.get(self.url.as_str(), parameters, credential).await?;
        success_protocol(&body.text).map_err(|failure| self.redacted(failure))
    }

    /// Sends one keyed GET and reads the complete body; any HTTP error status is a failure.
    async fn get(
        &self,
        url: &str,
        parameters: &[(&'static str, String)],
        credential: &Secret,
    ) -> Result<ProviderResponseBody, AttemptFailure> {
        let request = self
            .client
            .get(url)
            .query(parameters)
            .query(&[("api_key", credential.expose())]);
        // The key travels in the URL, so the URL never reaches the message.
        let response = request.send().await.map_err(|error| AttemptFailure {
            kind: AttemptErrorKind::Network,
            status: error.status().map(|status| status.as_u16()),
            message: redacted_urls_message(&error.without_url().to_string(), &self.credentials),
        })?;
        read_complete_protocol(response, &self.credentials, failure_message).await
    }

    fn redacted(&self, mut failure: AttemptFailure) -> AttemptFailure {
        failure.message = redacted_urls_message(&failure.message, &self.credentials);
        failure
    }

    fn settings(&self, target: AttemptTarget) -> ExecutionSettings {
        ExecutionSettings {
            provider: ROUTE.name(),
            target,
            retry_policy: self.retry_policy,
            deadline: self.deadline,
            attempt_timeout: Duration::from_secs(self.timeout_seconds),
            verbose: false,
            timeout_message: "SerpApi request timed out",
            model: None,
            transport: Some("http"),
            endpoint_host: None,
            breaker_event: None,
        }
    }
}

#[derive(Deserialize)]
struct Envelope {
    search_metadata: Option<Metadata>,
    error: Option<String>,
    search_information: Option<Information>,
    organic_results: Option<Vec<Value>>,
    serpapi_pagination: Option<Pagination>,
}

#[derive(Deserialize)]
struct Metadata {
    status: Option<String>,
}

#[derive(Deserialize)]
struct Information {
    organic_results_state: Option<String>,
}

#[derive(Deserialize)]
struct Pagination {
    next: Option<String>,
}

#[derive(Deserialize)]
struct ErrorBody {
    error: String,
}

/// Decides an HTTP 200 response: `Success` with results or exactly `Fully empty` succeeds,
/// `Error` is a Network failure the shared policy retries, and anything else is Runtime.
fn success_protocol(body: &str) -> Result<SearchResults, AttemptFailure> {
    let runtime = |message| refusal(AttemptErrorKind::Runtime, message);
    let envelope = serde_json::from_str::<Envelope>(body)
        .map_err(|error| runtime(format!("invalid SerpApi response: {error}")))?;
    let status = envelope
        .search_metadata
        .and_then(|metadata| metadata.status);
    match status.as_deref() {
        Some("Success") => {}
        Some("Error") => {
            return Err(refusal(
                AttemptErrorKind::Network,
                format!(
                    "SerpApi reported an error: {}",
                    envelope.error.as_deref().unwrap_or("no message")
                ),
            ));
        }
        Some(status) => {
            return Err(runtime(format!(
                "SerpApi returned search status `{status}`"
            )));
        }
        None => {
            return Err(runtime("SerpApi response has no search status".into()));
        }
    }
    let state = envelope
        .search_information
        .and_then(|information| information.organic_results_state);
    match (envelope.organic_results, state.as_deref()) {
        (Some(results), _) if !results.is_empty() => Ok(SearchResults::Found {
            results,
            has_next_page: envelope
                .serpapi_pagination
                .is_some_and(|pagination| pagination.next.is_some()),
        }),
        (None, Some("Fully empty")) => Ok(SearchResults::Empty),
        _ => Err(runtime(format!(
            "SerpApi reported success without results (results state `{}`)",
            state.as_deref().unwrap_or("none")
        ))),
    }
}

fn failure_message(body: &str, status: u16) -> String {
    serde_json::from_str::<ErrorBody>(body).map_or_else(
        |_| format!("SerpApi returned HTTP {status}"),
        |body| format!("SerpApi returned HTTP {status}: {}", body.error),
    )
}

#[cfg(test)]
mod tests {
    use serde_json::{Value, json};

    use super::{SearchResults, success_protocol};
    use crate::types::AttemptErrorKind;

    fn decided(body: &Value) -> Result<SearchResults, (AttemptErrorKind, String)> {
        success_protocol(&body.to_string()).map_err(|failure| (failure.kind, failure.message))
    }

    #[test]
    fn results_with_success_are_found_with_the_next_page_signal() {
        let page = |pagination: Value| {
            json!({
                "search_metadata": {"status": "Success"},
                "organic_results": [{"title": "Time series momentum"}],
                "serpapi_pagination": pagination
            })
        };
        let results = [
            json!({"next": "https://serpapi.com/search.json?start=20"}),
            json!({"current": 1}),
            Value::Null,
        ]
        .map(|pagination| decided(&page(pagination)));

        let found = |has_next_page| {
            Ok(SearchResults::Found {
                results: vec![json!({"title": "Time series momentum"})],
                has_next_page,
            })
        };
        assert_eq!(results, [found(true), found(false), found(false)]);
    }

    #[test]
    fn a_fully_empty_success_without_results_is_empty() {
        let body = json!({
            "search_metadata": {"status": "Success"},
            "search_information": {"organic_results_state": "Fully empty"}
        });

        assert_eq!(decided(&body), Ok(SearchResults::Empty));
    }

    #[test]
    fn an_error_status_is_a_network_failure_with_serpapi_message() {
        let body = json!({
            "search_metadata": {"id": "6ac6613da20802ffe5e7c8be", "status": "Error"},
            "error": "Google hasn't returned any results for this query."
        });

        assert_eq!(
            decided(&body),
            Err((
                AttemptErrorKind::Network,
                "SerpApi reported an error: Google hasn't returned any results for this query."
                    .to_owned()
            ))
        );
    }

    #[test]
    fn any_other_status_or_results_shape_is_a_runtime_failure() {
        let results = [
            json!({
                "search_metadata": {"status": "Success"},
                "search_information": {"organic_results_state": "Results for exact spelling"}
            }),
            json!({"search_metadata": {"status": "Success"}, "organic_results": []}),
            json!({
                "search_metadata": {"status": "Success"},
                "search_information": {"organic_results_state": "Fully empty"},
                "organic_results": []
            }),
            json!({"search_metadata": {}, "organic_results": [{"title": "x"}]}),
            json!({"search_metadata": {"status": "Processing"}, "organic_results": [{"title": "x"}]}),
        ]
        .map(|body| decided(&body));

        let runtime = |message: &str| Err((AttemptErrorKind::Runtime, message.to_owned()));
        assert_eq!(
            results,
            [
                runtime(
                    "SerpApi reported success without results (results state `Results for exact spelling`)"
                ),
                runtime("SerpApi reported success without results (results state `none`)"),
                runtime("SerpApi reported success without results (results state `Fully empty`)"),
                runtime("SerpApi response has no search status"),
                runtime("SerpApi returned search status `Processing`"),
            ]
        );
    }

    #[test]
    fn a_body_that_is_no_serpapi_envelope_is_a_runtime_failure() {
        let failure = decided(&json!({
            "search_metadata": {"status": "Success"},
            "organic_results": {"position": 1}
        }))
        .unwrap_err();

        assert_eq!(
            (
                failure.0,
                failure.1.starts_with("invalid SerpApi response: ")
            ),
            (AttemptErrorKind::Runtime, true),
            "message: {}",
            failure.1
        );
    }
}

//! The `hn_api` route: one route over two official Hacker News endpoints (ADR 0027).
//!
//! Algolia's HN Search API searches items and returns a whole discussion tree in one request;
//! the official Firebase API knows the rank Hacker News shows and the live counts. Firebase only
//! enriches what Algolia returns: when an enrichment request fails, the Algolia result stands
//! and one diagnostic says what is missing. The story lists exist only on Firebase, so a list
//! request failure fails `stories`. Every request to either endpoint follows the route's one
//! access policy.

use std::time::Duration;

use chrono::DateTime;
use reqwest::{Client, StatusCode};
use serde::Deserialize;
use serde::de::DeserializeOwned;

use crate::catalog::{PlatformOperation, ProviderId};
use crate::config::HnRouteRuntimeConfig;
use crate::credentials::CredentialPool;
use crate::net::{
    AttemptFailure, RetryPolicy, combine_diagnostics, read_complete_protocol, send_provider_request,
};
use crate::providers::execution::{ExecutionOutcome, ExecutionSettings, execute_anonymous};
use crate::providers::shared::{acquire_window, other_platform_message, parameter_error};
use crate::rate_limit::RateLimiter;
use crate::types::{
    AttemptDisposition, AttemptErrorKind, AttemptTarget, ContentDepth, Deadline, FullTextSource,
    HnItemData, HnItemType, HnRef, Platform, PlatformFetchOutcome, PlatformFetchRequest,
    PlatformItem, PlatformItemData, PlatformRef, ProviderAttempt, ProviderError,
};

#[path = "hn_markup.rs"]
mod hn_markup;
#[path = "hn_api_search.rs"]
mod search;
#[path = "hn_api_thread.rs"]
mod thread;

pub(crate) use search::search_support;

use hn_markup::hn_markdown;
use thread::{ThreadNode, ThreadRoot};

const ROUTE: ProviderId = ProviderId::HnApi;
const PLATFORM: Platform = Platform::Hn;

/// Returns whether the route can fetch at the requested depth; it never sends a request. The
/// item type is unknown until the item is read, so a comment asked for its full text fails
/// later.
pub(crate) fn fetch_support(request: &PlatformFetchRequest) -> Result<(), String> {
    if !matches!(request.reference, PlatformRef::Hn(_)) {
        return Err(other_platform_message(ROUTE, request.reference.platform()));
    }
    match request.depth {
        ContentDepth::Thread | ContentDepth::Metadata | ContentDepth::FullText => Ok(()),
        depth => Err(format!(
            "{} cannot fetch at depth `{}`",
            ROUTE.name(),
            depth.as_str()
        )),
    }
}

/// The two endpoints of the route.
#[derive(Clone, Copy)]
enum Endpoint {
    Algolia,
    Firebase,
}

impl Endpoint {
    const fn label(self) -> &'static str {
        match self {
            Self::Algolia => "HN Search API",
            Self::Firebase => "HN Firebase API",
        }
    }

    const fn timeout_message(self) -> &'static str {
        match self {
            Self::Algolia => "HN Search API request timed out",
            Self::Firebase => "HN Firebase API request timed out",
        }
    }
}

pub(crate) struct HnApi {
    config: HnRouteRuntimeConfig,
    client: Client,
    // The route needs no credentials; the empty pool only drives shared redaction.
    credentials: CredentialPool,
    limiter: RateLimiter,
    retry_policy: RetryPolicy,
    deadline: Deadline,
}

impl HnApi {
    pub(crate) fn new(
        config: HnRouteRuntimeConfig,
        client: Client,
        limiter: RateLimiter,
        retry_policy: RetryPolicy,
        deadline: Deadline,
    ) -> Self {
        Self {
            config,
            client,
            credentials: CredentialPool::new(ROUTE.name(), Vec::new()),
            limiter,
            retry_policy,
            deadline,
        }
    }

    /// Reads one item at the requested depth.
    pub(crate) async fn fetch(
        &self,
        request: &PlatformFetchRequest,
    ) -> Result<PlatformFetchOutcome, ProviderError> {
        let PlatformRef::Hn(reference) = request.reference else {
            return Err(parameter_error(other_platform_message(
                ROUTE,
                request.reference.platform(),
            )));
        };
        fetch_support(request).map_err(parameter_error)?;
        let mut trail = Trail::default();
        let (item, content_source) = match request.depth {
            ContentDepth::Thread => self.read_thread(reference, &mut trail).await?,
            ContentDepth::FullText => {
                let item = self.read_metadata(reference, &mut trail).await?;
                let source = full_text_source(reference, &item)
                    .map_err(|(kind, message)| trail.error(kind, message))?;
                (item, source)
            }
            _ => (
                self.read_metadata(reference, &mut trail).await?,
                FullTextSource::Urls(Vec::new()),
            ),
        };
        Ok(PlatformFetchOutcome {
            item,
            content_source,
            diagnostic: trail.diagnostic(),
            attempts: trail.attempts,
        })
    }

    /// Asks the Firebase API for its newest item ID, which proves the endpoint answers.
    pub(crate) async fn probe_firebase(&self) -> Result<(), ProviderError> {
        self.get::<u64>(
            Endpoint::Firebase,
            "maxitem.json",
            &[],
            PlatformOperation::Search.as_str(),
        )
        .await
        .map(|_| ())
    }

    /// Reads the item metadata: the Algolia record, with the live counts and the deleted or
    /// dead flags of the Firebase item. An item too new for Algolia is built from Firebase.
    async fn read_metadata(
        &self,
        reference: HnRef,
        trail: &mut Trail,
    ) -> Result<PlatformItem, ProviderError> {
        let operation = PlatformOperation::Fetch.as_str();
        let hits = trail.required(self.search_objects(&[reference.id()], operation).await)?;
        let indexed = hits
            .into_iter()
            .find(|hit| hit.object_id == reference.to_string())
            .map(|hit| hit.into_item(ContentDepth::Metadata))
            .transpose()
            .map_err(|message| trail.error(AttemptErrorKind::Runtime, message))?;
        let live = trail.optional(self.firebase_item(reference.id(), operation).await);
        match (indexed, live) {
            (_, Ok(Some(live))) if live.deleted || live.dead => Err(trail.error(
                AttemptErrorKind::Parameter,
                format!("HN item hn:{reference} is deleted or dead"),
            )),
            (Some(mut item), Ok(Some(live))) => {
                live.correct_counts(&mut item);
                Ok(item)
            }
            (Some(item), Ok(None)) => Ok(item),
            (Some(item), Err(error)) => {
                trail.note(format!(
                    "HN Firebase API unavailable ({}); points and comment counts may lag",
                    error.message
                ));
                Ok(item)
            }
            (None, Ok(Some(live))) => live
                .into_item(ContentDepth::Metadata)
                .map_err(|message| trail.error(AttemptErrorKind::Runtime, message)),
            (None, Ok(None)) => Err(trail.error(
                AttemptErrorKind::Parameter,
                format!("HN item not found: hn:{reference}"),
            )),
            (None, Err(error)) => Err(trail.error(error.kind, error.message)),
        }
    }

    /// Reads the discussion rooted at the item and renders it as Markdown. Top-level comments
    /// follow the Firebase rank; without it, every comment is in time order.
    async fn read_thread(
        &self,
        reference: HnRef,
        trail: &mut Trail,
    ) -> Result<(PlatformItem, FullTextSource), ProviderError> {
        let operation = PlatformOperation::Fetch.as_str();
        let tree = trail.required(self.items_tree(reference).await)?;
        let live = match trail.optional(self.firebase_item(reference.id(), operation).await) {
            Ok(Some(live)) if live.deleted || live.dead => {
                return Err(trail.error(
                    AttemptErrorKind::Parameter,
                    format!("HN item hn:{reference} is deleted or dead"),
                ));
            }
            Ok(Some(live)) => Some(live),
            Ok(None) => {
                trail.note(format!(
                    "HN Firebase API has no item hn:{reference}; comments are in chronological order"
                ));
                None
            }
            Err(error) => {
                trail.note(format!(
                    "HN Firebase API unavailable ({}); comments are in chronological order and counts may lag",
                    error.message
                ));
                None
            }
        };
        let item_type = HnItemType::parse(&tree.item_type).ok_or_else(|| {
            trail.error(
                AttemptErrorKind::Runtime,
                format!(
                    "HN item hn:{reference} has an unknown type `{}`",
                    tree.item_type
                ),
            )
        })?;
        let story_id = tree.story_id.filter(|id| *id != reference.id());
        let mut story_title = None;
        if item_type == HnItemType::Comment
            && let Some(story_id) = story_id
        {
            match trail.optional(self.firebase_item(story_id, operation).await) {
                Ok(story) => story_title = story.and_then(|story| story.title),
                Err(error) => trail.note(format!(
                    "HN Firebase API unavailable ({}); the story title is missing",
                    error.message
                )),
            }
        }
        let (root, order) = ThreadRoot::new(tree, live.as_ref().map(|live| live.kids.as_slice()));
        let delivered = root.comment_count();
        let comments = live.as_ref().and_then(|live| live.descendants).or_else(|| {
            matches!(item_type, HnItemType::Story | HnItemType::Poll).then_some(delivered as u64)
        });
        let item = PlatformItem {
            url: reference.canonical_url(),
            reference: PlatformRef::Hn(reference),
            depth: ContentDepth::Thread,
            title: (item_type != HnItemType::Comment)
                .then(|| root.node().title.clone())
                .flatten(),
            authors: root.node().author.clone().into_iter().collect(),
            published: published(root.node().created_at_i),
            data: PlatformItemData::Hn(HnItemData {
                item_type,
                link_url: non_empty(root.node().url.clone()),
                points: live
                    .as_ref()
                    .and_then(|live| live.score)
                    .or(root.node().points),
                comments,
                text: root.node().text.as_deref().and_then(hn_markdown),
                story_ref: comment_ref(item_type, story_id),
                story_title: (item_type == HnItemType::Comment)
                    .then_some(story_title)
                    .flatten(),
                parent_ref: comment_ref(item_type, root.node().parent_id),
                comments_delivered: Some(delivered),
                order: Some(order),
            }),
        };
        let markdown = root.render(&item);
        Ok((item, FullTextSource::Native(markdown)))
    }

    /// Searches Algolia for the items with these IDs, of any type, in one request.
    async fn search_objects(
        &self,
        ids: &[u64],
        operation: &'static str,
    ) -> Result<ExecutionOutcome<Vec<search::Hit>>, ProviderError> {
        let filters = ids
            .iter()
            .map(|id| format!("objectID:{id}"))
            .collect::<Vec<_>>()
            .join(" OR ");
        let query = [("filters", filters), ("hitsPerPage", ids.len().to_string())];
        let outcome = self
            .get::<search::SearchResponse>(Endpoint::Algolia, "search", &query, operation)
            .await?;
        Ok(ExecutionOutcome {
            value: outcome.value.hits,
            attempts: outcome.attempts,
            diagnostic: outcome.diagnostic,
        })
    }

    /// Reads the whole Algolia tree rooted at the item.
    async fn items_tree(
        &self,
        reference: HnRef,
    ) -> Result<ExecutionOutcome<ThreadNode>, ProviderError> {
        let path = format!("items/{reference}");
        self.get_with(
            Endpoint::Algolia,
            &path,
            &[],
            PlatformOperation::Fetch.as_str(),
            thread::decode_tree,
        )
        .await
        .map_err(|mut error| {
            if let Some(attempt) = error
                .attempts
                .last_mut()
                .filter(|attempt| attempt.http_status == Some(404))
            {
                attempt.message = format!("HN item not found: hn:{reference}");
                error.message.clone_from(&attempt.message);
            }
            error
        })
    }

    /// Reads one Firebase item; `None` when Firebase has no such item.
    async fn firebase_item(
        &self,
        id: u64,
        operation: &'static str,
    ) -> Result<ExecutionOutcome<Option<FirebaseItem>>, ProviderError> {
        self.get(
            Endpoint::Firebase,
            &format!("item/{id}.json"),
            &[],
            operation,
        )
        .await
    }

    /// Sends one GET to an endpoint under the route's access policy and decodes the JSON body.
    async fn get<T: DeserializeOwned>(
        &self,
        endpoint: Endpoint,
        path: &str,
        query: &[(&str, String)],
        operation: &'static str,
    ) -> Result<ExecutionOutcome<T>, ProviderError> {
        self.get_with(endpoint, path, query, operation, decode_json)
            .await
    }

    /// Sends one GET to an endpoint under the route's access policy; a body `decode` rejects
    /// fails the attempt as Runtime.
    async fn get_with<T>(
        &self,
        endpoint: Endpoint,
        path: &str,
        query: &[(&str, String)],
        operation: &'static str,
        decode: fn(&str) -> Result<T, String>,
    ) -> Result<ExecutionOutcome<T>, ProviderError> {
        let base = match endpoint {
            Endpoint::Algolia => &self.config.url,
            Endpoint::Firebase => &self.config.firebase_url,
        };
        let url = &format!("{}/{path}", base.trim_end_matches('/'));
        let failure_message = match endpoint {
            Endpoint::Algolia => algolia_failure_message,
            Endpoint::Firebase => firebase_failure_message,
        };
        execute_anonymous(
            self.settings(endpoint, operation),
            move |deadline| async move {
                let _permit = acquire_window(&self.limiter, deadline).await?;
                let request = self.client.get(url).query(query);
                let response = send_provider_request(request, &self.credentials).await?;
                let body =
                    read_complete_protocol(response, &self.credentials, failure_message).await?;
                let value = decode(&body.text).map_err(|error| AttemptFailure {
                    kind: AttemptErrorKind::Runtime,
                    status: Some(body.status),
                    message: format!("invalid {} response: {error}", endpoint.label()),
                })?;
                Ok((Some(body.status), value))
            },
        )
        .await
    }

    fn settings(&self, endpoint: Endpoint, operation: &'static str) -> ExecutionSettings {
        ExecutionSettings {
            provider: ROUTE.name(),
            target: AttemptTarget::platform(PLATFORM.as_str(), operation),
            retry_policy: self.retry_policy,
            deadline: self.deadline,
            attempt_timeout: Duration::from_secs(self.config.timeout_seconds),
            verbose: false,
            timeout_message: endpoint.timeout_message(),
            model: None,
            transport: Some("http"),
            endpoint_host: None,
            breaker_event: None,
        }
    }
}

/// Says where the full text of an item lives: the page a link item points to, or the item's
/// own title and body. A comment or poll option is part of a discussion, not a document.
fn full_text_source(
    reference: HnRef,
    item: &PlatformItem,
) -> Result<FullTextSource, (AttemptErrorKind, String)> {
    let PlatformItemData::Hn(data) = &item.data else {
        unreachable!("the hn route builds hn items")
    };
    let kind = match data.item_type {
        HnItemType::Comment => Some("a comment"),
        HnItemType::Pollopt => Some("a poll option"),
        HnItemType::Story | HnItemType::Poll | HnItemType::Job => None,
    };
    if let Some(kind) = kind {
        return Err((
            AttemptErrorKind::Parameter,
            format!(
                "hn:{reference} is {kind}; full_text applies to stories, polls, and jobs; use --depth thread"
            ),
        ));
    }
    if let Some(url) = &data.link_url {
        return Ok(FullTextSource::Urls(vec![url.clone()]));
    }
    let body = [
        item.title.as_ref().map(|title| format!("# {title}")),
        data.text.clone(),
    ]
    .into_iter()
    .flatten()
    .collect::<Vec<_>>()
    .join("\n\n");
    if body.is_empty() {
        return Err((
            AttemptErrorKind::Quality,
            format!("hn:{reference} has no title or text to read"),
        ));
    }
    Ok(FullTextSource::Native(body))
}

/// The attempts and diagnostics of the requests one operation sends in sequence.
#[derive(Default)]
struct Trail {
    attempts: Vec<ProviderAttempt>,
    notes: Vec<String>,
}

impl Trail {
    fn record<T>(&mut self, outcome: ExecutionOutcome<T>) -> T {
        self.attempts.extend(outcome.attempts);
        self.notes.extend(outcome.diagnostic);
        outcome.value
    }

    /// Takes the result of a request the operation cannot do without; a failure carries every
    /// attempt so far.
    fn required<T>(
        &mut self,
        result: Result<ExecutionOutcome<T>, ProviderError>,
    ) -> Result<T, ProviderError> {
        match result {
            Ok(outcome) => Ok(self.record(outcome)),
            Err(error) => Err(self.fail(error)),
        }
    }

    /// Takes the result of an enrichment request; a failure keeps its attempts here and returns
    /// the error for the caller to note or escalate.
    fn optional<T>(
        &mut self,
        result: Result<ExecutionOutcome<T>, ProviderError>,
    ) -> Result<T, ProviderError> {
        result
            .map(|outcome| self.record(outcome))
            .map_err(|mut error| {
                self.attempts.append(&mut error.attempts);
                self.notes.extend(error.diagnostic.take());
                error
            })
    }

    fn note(&mut self, note: String) {
        self.notes.push(note);
    }

    fn fail(&mut self, mut error: ProviderError) -> ProviderError {
        let mut attempts = std::mem::take(&mut self.attempts);
        attempts.append(&mut error.attempts);
        error.attempts = attempts;
        error.diagnostic = combine_diagnostics(self.notes.drain(..).chain(error.diagnostic));
        error
    }

    /// Fails the operation on what its requests returned: the last attempt records the failure,
    /// so the chain attributes it to this route.
    fn error(&mut self, kind: AttemptErrorKind, message: String) -> ProviderError {
        if let Some(attempt) = self.attempts.last_mut() {
            attempt.disposition = AttemptDisposition::Failed;
            attempt.error_kind = Some(kind);
            attempt.message.clone_from(&message);
        }
        self.fail(ProviderError {
            kind,
            message,
            attempts: Vec::new(),
            verbose: false,
            diagnostic: None,
            redirected_library_id: None,
        })
    }

    fn diagnostic(&self) -> Option<String> {
        combine_diagnostics(self.notes.iter().cloned())
    }
}

/// One Firebase item. Firebase omits every absent field, so each one is optional.
#[derive(Deserialize)]
struct FirebaseItem {
    id: u64,
    #[serde(rename = "type")]
    item_type: Option<String>,
    by: Option<String>,
    time: Option<i64>,
    text: Option<String>,
    title: Option<String>,
    url: Option<String>,
    score: Option<u64>,
    descendants: Option<u64>,
    /// The direct replies, in the rank Hacker News shows.
    #[serde(default)]
    kids: Vec<u64>,
    parent: Option<u64>,
    #[serde(default)]
    deleted: bool,
    #[serde(default)]
    dead: bool,
}

impl FirebaseItem {
    /// Replaces an indexed item's counts with the live ones, where Firebase has them.
    fn correct_counts(&self, item: &mut PlatformItem) {
        if let PlatformItemData::Hn(data) = &mut item.data {
            data.points = self.score.or(data.points);
            data.comments = self.descendants.or(data.comments);
        }
    }

    /// Builds an item from Firebase alone; a comment's story is unknown here.
    fn into_item(self, depth: ContentDepth) -> Result<PlatformItem, String> {
        let item_type = self
            .item_type
            .as_deref()
            .and_then(HnItemType::parse)
            .ok_or_else(|| format!("HN item hn:{} has an unknown type", self.id))?;
        let reference = HnRef::new(self.id)
            .ok_or_else(|| format!("HN Firebase API returned invalid item ID {}", self.id))?;
        Ok(PlatformItem {
            url: reference.canonical_url(),
            reference: PlatformRef::Hn(reference),
            depth,
            title: (item_type != HnItemType::Comment)
                .then_some(self.title)
                .flatten(),
            authors: self.by.into_iter().collect(),
            published: published(self.time),
            data: PlatformItemData::Hn(HnItemData {
                item_type,
                link_url: non_empty(self.url),
                points: self.score,
                comments: self.descendants,
                text: self.text.as_deref().and_then(hn_markdown),
                story_ref: None,
                story_title: None,
                parent_ref: comment_ref(item_type, self.parent),
                comments_delivered: None,
                order: None,
            }),
        })
    }
}

fn decode_json<T: DeserializeOwned>(body: &str) -> Result<T, String> {
    serde_json::from_str(body).map_err(|error| error.to_string())
}

/// Returns the ref of a comment's story or parent; `None` for other item types.
fn comment_ref(item_type: HnItemType, id: Option<u64>) -> Option<PlatformRef> {
    (item_type == HnItemType::Comment)
        .then_some(id)
        .flatten()
        .and_then(HnRef::new)
        .map(PlatformRef::Hn)
}

/// Formats a Unix time as a UTC ISO 8601 timestamp to the second.
fn published(seconds: Option<i64>) -> Option<String> {
    seconds
        .and_then(|seconds| DateTime::from_timestamp(seconds, 0))
        .map(|time| time.format("%Y-%m-%dT%H:%M:%SZ").to_string())
}

fn non_empty(value: Option<String>) -> Option<String> {
    value
        .map(|value| value.trim().to_owned())
        .filter(|value| !value.is_empty())
}

#[derive(Deserialize)]
struct AlgoliaError {
    message: String,
}

fn algolia_failure_message(body: &str, status: u16) -> String {
    serde_json::from_str::<AlgoliaError>(body).map_or_else(
        |_| format!("HN Search API returned HTTP {status}"),
        |error| format!("HN Search API rejected the request: {}", error.message),
    )
}

fn firebase_failure_message(_body: &str, status: u16) -> String {
    let reason = StatusCode::from_u16(status)
        .ok()
        .and_then(|status| status.canonical_reason())
        .map(|reason| format!(" ({reason})"))
        .unwrap_or_default();
    format!("HN Firebase API returned HTTP {status}{reason}")
}

